      "id": "SN-N2-S02-Q1",
      "isBookmarked": false,
      "qTrans": "【해석】\n돼지가 멧돼지에게 자랑을 늘어놓았습니다. \"나만큼 훌륭한 팔자도 없을 거야. 먹는 것부터 자는 것까지 전부 인간이 돌봐주고, 맛있는 음식은 물릴 정도로 먹으니 이렇게 살이 쪘지. 인간과 싸우지 않아도 되니 엄니 따위는 필요(주1)도 없어. 나와 자네는 친척이라던데, 같...\n\n【질문】\n문: 필자가 이 문장에서 전하고자 했던 것은 무엇인가?",
