    "SN-N2-S01-Q1": {
      "qRuby": "【지문】\n만화와 문학의 세계 (マンガと文学の世界)\n\n【문제】\n問 筆者はマンガと文学の世界との共通点はどのようなものだと言っているか。",
      "userAnswer": "②",
      "firstWrongDate": 1791777249417,
      "isBookmarked": false,
      "level": "N1",
      "id": "SN-N2-S01-Q1",
      "qPlain": "【지문 요약】\nマンガが描く世界は、人物であれ世界であれ、現実の世界のイメージを基本的には基礎としながらも、極端な誇張や省略をしたり、現実にはあり得ない世界を自由に構築したりすることが許される。このような制約の少なさの点では、テキストであらゆるものを表現しうる文学の世界とも共通する点が多い。文学の世界では実際の視覚情報を直接扱わないことでテキストで世界を描くことでこの自由度...\n\n【문제】\n問 筆者はマンガと文学の世界との共通点はどのようなものだと言っているか。",
      "typeCode": "reading_short",
      "lastWrongDate": 1791777249417,
      "isMastered": false,
      "instruction": "[지문: 만화와 문학의 세계 (マンガと文学の世界)] 問 筆者はマンガと文学の世界との共通点はどのようなものだと言っているか。",
      "typeName": "독해 - 단문 독해",
      "expl": {
        "main": "[정답 근거] このような制約の少なさの点では、テキストであらゆるものを表現しうる文学の世界とも共通する点が多い。\n\n지문에서 만화는 현실의 이미지를 기초로 삼으면서도 과장·생략을 통해 있을 수 없는 세계를 자유롭게 구축할 수 있으며, '이러한 제약의 적음'이라는 점에서 문학의 세계와 공통된다고 하였으므로 ④번이 정답입니다.",
        "choices": [
          {
            "marker": "①",
            "note": "제약이 '전혀 없다(まったくない)'는 것은 지나친 과장입니다 (본문: 制約の少なさ)."
          },
          {
            "marker": "②",
            "note": "시각 정보를 직접 다루지 않는 것은 문학만의 특징이며, 만화는 시각 표현을 직접 사용합니다."
          },
          {
            "marker": "③",
            "note": "실사의 제약을 벗어난 것은 만화의 시각적 성격이지 문학과의 공통점이 아닙니다."
          },
          {
            "marker": "④",
            "note": "현실을 바탕으로 허구의 세계를 자유롭게 구축하며 제약이 적다는 본문과 정확히 일치합니다."
          }
        ]
      },
      "ansKo": "④ 현실을 기초로 하면서도, 허구의 세계를 구축할 수 있는 제약이 적은 점",
      "qTrans": "【해석】\n만화가 그리는 세계는 인물이든 세계이든 현실 세계의 이미지를 기본적으로는 기초로 하면서도, 극단적인 과장이나 생략을 하거나 현실에는 있을 수 없는 세계를 자유롭게 구축하는 것이 허용된다. 이러한 제약의 적음이라는 점에서는 텍스트로 모든 것을 표현할 수 있는 문학의 세계...\n\n【질문】\n문: 필자는 만화와 문학의 세계와의 공통점은 어떠한 것이라고 말하고 있는가?",
      "count": 1,
      "options": [
        {
          "marker": "①",
          "copy": "現実の世界からかけ離れた、制約がまったくない点",
          "copyNoRuby": "現実の世界からかけ離れた、制約がまったくない点",
          "trans": "현실 세계로부터 동떨어진, 제약이 전혀 없는 점",
          "isCorrect": false
        },
        {
          "marker": "②",
          "copy": "視覚のイメージを直接扱うことなく、自由に現実の世界を描く点",
          "copyNoRuby": "視覚のイメージを直接扱うことなく、自由に現実の世界を描く点",
          "trans": "시각적 이미지를 직접 다루는 일 없이 자유롭게 현실의 세계를 그리는 점",
          "isCorrect": false
        },
        {
          "marker": "③",
          "copy": "現実の世界の視覚的イメージを主観的に変えて実写の制約を脱する点",
          "copyNoRuby": "現実の世界の視覚的イメージを主観的に変えて実写の制約を脱する点",
          "trans": "현실 세계의 시각적 이미지를 주관적으로 바꾸어 실사의 제약을 벗어나는 점",
          "isCorrect": false
        },
        {
          "marker": "④",
          "copy": "現実を基礎としながらも、虚構の世界を構築できる制約の少ない点",
          "copyNoRuby": "現実を基礎としながらも、虚構の世界を構築できる制約の少ない点",
          "trans": "현실을 기초로 하면서도, 허구의 세계를 구축할 수 있는 제약이 적은 점",
          "isCorrect": true
        }
      ],
      "userAnswerText": "視覚のイメージを直接扱うことなく、自由に現実の世界を描く点",
      "ansJa": "④ 現実を基礎としながらも、虚構の世界を構築できる制約の少ない点"
    },
